/* ==UserStyle==
@name Nitter Catppuccin
@namespace github.com/catppuccin/userstyles/styles/nitter
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/nitter
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/nitter/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Anitter
@description Soothing pastel theme for Nitter
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("nitter.net"),
  domain("nitter.unixfox.eu"),
  domain("nitter.42l.fr"),
  domain("nitter.fdn.fr"),
  domain("nitter.1d4.us"),
  domain("nitter.kavin.rocks"),
  domain("nitter.namazso.eu"),
  domain("nitter.hu"),
  domain("bird.trom.tf"),
  domain("nitter.it"),
  domain("twitter.censors.us"),
  domain("nitter.grimneko.de"),
  domain("n.hyperborea.cloud"),
  domain("nitter.ca"),
  domain("twitter.076.ne.jp"),
  domain("nitter.mstdn.social"),
  domain("nitter.fly.dev"),
  domain("nitter.weiler.rocks"),
  domain("nitter.sethforprivacy.com"),
  domain("nttr.stream"),
  domain("nitter.tiekoetter.com"),
  domain("nitter.spaceint.fr"),
  domain("nitter.privacy.com.denitter.mastodon.pro"),
  domain("nitter.notraxx.chnitter.poast.org"),
  domain("nitter.bird.froth.zone"),
  domain("nitter.dcs0.hu"),
  domain("twitter.beparanoid.de"),
  domain("n.ramle.be"),
  domain("nitter.cz"),
  domain("nitter.privacydev.net"),
  domain("tweet.lambda.dance"),
  domain("nitter.kylrth.com"),
  domain("nitter.oishi-ra.men"),
  domain("nitter.foss.wtf"),
  domain("nitter.priv.pw"),
  domain("t.com.sb"),
  domain("xcancel.com"),
  domain("nitter.poast.org") {
  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    body {
      --bg_color: @mantle;
      --fg_color: @text;
      --fg_faded: @subtext1;
      --fg_dark: @accent;
      --fg_nav: @accent;
      --bg_panel: @crust;
      --bg_elements: @base;
      --bg_overlays: @base;
      --bg_hover: @crust;
      --grey: @subtext1;
      --dark_grey: @overlay0;
      --darker_grey: @base;
      --darkest_grey: @mantle;
      --border_grey: @base;
      --accent: @accent;
      --accent_light: lighten(@accent, 10%);
      --accent_dark: darken(@accent, 10%);
      --accent_border: darken(@accent, 10%);
      --play_button: @accent;
      --play_button_hover: @accent;
      --more_replies_dots: darken(@accent, 10%);
      --error_red: @red;
      --verified_blue: @blue;
      --icon_text: @text;
      --tab: @text;
      --tab_selected: @accent;
      --profile_stat: @text;
      --verified_government: @subtext0;
      --verified_business: @yellow;
      background-color: var(--bg_color);
      color: var(--fg_color);
      line-height: 1.3;
      margin: 0;
    }

    /* logo */
    img.site-logo {
      @svg: escape(
        '<svg xmlns="http://www.w3.org/2000/svg" width="500" height="500" fill="none"><path stroke="@{accent}" stroke-linejoin="round" stroke-width="20" d="M145 41H81v418h78V183.5L355 459h64V41h-78v275.5z"/></svg>'
      );
      content: url("data:image/svg+xml,@{svg}");
    }

    /* Fix Poll Leader color */
    .poll-meter.leader {
      color: var(--bg_color);
    }

    /* xcancel "verifying your request" */
    [style="background-color:#1f1f1f;color:#1f1f1f;font-family:Arial,Helvetica,sans-serif;font-size:100%;"] {
      background: @base !important;
      h1,
      h2,
      p,
      #status {
        color: @accent !important;
      }
      [style="width:auto;margin:16px auto;border:1px solid #FF6C60;background-color:#1f1f1f;border-radius:3px 3px 3px 3px;padding:10px;"] {
        background: @base !important;
        border-color: @accent !important;
      }
    }

    /* error text color contrast */
    .error-panel {
      color: @crust;
      a {
        color: @crust;
        text-decoration: underline;
      }
    }

    /* twitter blue verification checkmark contrast */
    .verified-icon.blue {
      color: @crust;
    }
  }
}

#rgbify(@color) {
  @rgb: red(@color) green(@color) blue(@color);
}

